static bool
hdlc_byte_needs_escape(uint8_t byte)
{
        switch(byte) {
        case HDLC_BYTE_SPECIAL:
        case HDLC_BYTE_ESC:
        case HDLC_BYTE_FLAG:
        case HDLC_BYTE_XOFF:
        case HDLC_BYTE_XON:
                return true;

        default:
                return false;
        }
}

